{"content":""""Independent scheduler calendar model campaign for extended phase 13."""
import argparse
import hashlib
import json
from pathlib import Path
import math
import random
import sys
import tempfile
import time
import uuid
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from joblab import Queue

ARTIFACTS = ROOT / 'artifacts' / 'extended-13'


class CalendarModel:
    """Only calendar arithmetic and cursor rules; no production imports or SQL."""
    def __init__(self):
        self.now = 1000.0
        self.schedules = {}
        self.fires = []

    def add(self, label, payload, start, interval):
        self.schedules[label] = {'payload': payload, 'start': start, 'interval': interval,
                                 'next_index': 0, 'status': 'active'}

    def tick(self):
        created = []
        for label, schedule in sorted(self.schedules.items()):
            if schedule['status'] != 'active' or self.now < schedule['start']:
                continue
            if schedule['interval'] is None:
                occurrence = 0
            else:
                occurrence = math.floor((self.now - schedule['start']) / schedule['interval'])
            if occurrence < schedule['next_index']:
                continue
            due = schedule['start'] if schedule['interval'] is None else schedule['start'] + occurrence * schedule['interval']
            self.fires.append((label, occurrence, due))
            created.append((label, occurrence, due))
            schedule['next_index'] = occurrence + 1
            if schedule['interval'] is None:
                schedule['status'] = 'completed'
        return created

    def cancel(self, label):
        if self.schedules[label]['status'] == 'active':
            self.schedules[label]['status'] = 'cancelled'
            return True
        return False


class SchedulerRunner:
    def __init__(self, path):
        self.model = CalendarModel()
        self.q = Queue(path, clock=lambda: self.model.now)
        self.ids = {}
        self.counts = {}

    def check(self):
        schedules = self.q.db.execute('SELECT * FROM schedules ORDER BY id').fetchall()
        self.assert_equal(len(schedules), len(self.model.schedules), 'schedule count')
        reverse = {value: label for label, value in self.ids.items()}
        seen_cursors = {}
        for row in schedules:
            label = reverse[row['id']]
            expected = self.model.schedules[label]
            self.assert_equal(row['start_at'], expected['start'], label + ' start')
            self.assert_equal(row['interval'], expected['interval'], label + ' interval')
            self.assert_equal(row['next_index'], expected['next_index'], label + ' cursor')
            self.assert_equal(row['status'], expected['status'], label + ' status')
            seen_cursors[label] = row['next_index']
        fires = self.q.db.execute(
            'SELECT schedule_id, occurrence, due_at, job_id FROM schedule_fires ORDER BY schedule_id, occurrence'
        ).fetchall()
        actual_fires = []
        for row in fires:
            label = reverse[row['schedule_id']]
            actual_fires.append((label, row['occurrence'], row['due_at']))
        self.assert_equal(actual_fires, sorted(self.model.fires), 'fire records')
        self.assert_equal(len({(a, b) for a, b, _ in actual_fires}), len(actual_fires), 'duplicate occurrences')
        jobs = self.q.list()
        self.assert_equal(len(jobs), len(self.model.fires), 'materialized job count')
        self.assert_equal(sorted(job['available_at'] for job in jobs),
                          sorted(due for _, _, due in self.model.fires), 'job due times')

    @staticmethod
    def assert_equal(actual, expected, message):
        if actual != expected:
            raise AssertionError('%s: expected %r, got %r' % (message, expected, actual))

    def apply(self, operation):
        kind = operation['op']
        if kind == 'schedule':
            label = operation['label']
            self.model.add(label, operation['payload'], operation['start'], operation['interval'])
            actual = self.q.schedule(operation['payload'], start_at=operation['start'], interval=operation['interval'])
            self.ids[label] = actual['id']
        elif kind == 'advance':
            self.model.now = operation['to']
        elif kind == 'tick':
            expected = self.model.tick()
            actual = self.q.tick()
            self.assert_equal(len(actual), len(expected), 'tick result count')
            for job, (label, _, due) in zip(actual, expected):
                self.assert_equal(job['payload'], self.model.schedules[label]['payload'], 'tick payload')
                self.assert_equal(job['available_at'], due, 'tick due')
        elif kind == 'cancel':
            label = operation['label']
            expected = self.model.cancel(label)
            actual = self.q.cancel_schedule(self.ids[label])
            self.assert_equal(actual, expected, 'cancel result')
        elif kind == 'reopen':
            self.q.close()
            self.q = Queue(self.path, clock=lambda: self.model.now)
        else:
            raise AssertionError('unknown operation')
        self.counts[kind] = self.counts.get(kind, 0) + 1
        self.check()

    def operation(self, rng, step):
        active = [label for label, schedule in self.model.schedules.items() if schedule['status'] == 'active']
        if step == 0 or (not self.model.schedules and step < 5):
            label = 's' + str(step)
            return {'op': 'schedule', 'label': label, 'payload': {'seed_step': step},
                    'start': self.model.now + rng.choice([0, 1, 3, 10]),
                    'interval': rng.choice([None, 2.0, 5.0, 10.0])}
        choices = ['advance', 'tick', 'tick', 'reopen']
        if active:
            choices += ['cancel', 'cancel']
        if len(self.model.schedules) < 8:
            choices += ['schedule']
        kind = rng.choice(choices)
        if kind == 'schedule':
            label = 's' + str(step)
            return {'op': kind, 'label': label, 'payload': {'seed_step': step},
                    'start': self.model.now + rng.choice([0, 1, 3, 10]),
                    'interval': rng.choice([None, 2.0, 5.0, 10.0])}
        if kind == 'advance':
            boundaries = [self.model.now + x for x in (-3.0, -0.25, 0.25, 1.0, 5.0, 10.0, 25.0)]
            for schedule in self.model.schedules.values():
                boundaries.append(schedule['start'])
                if schedule['interval'] is not None:
                    boundaries.append(schedule['start'] + schedule['interval'] * rng.randint(0, 8))
            choices = [x for x in boundaries if x != self.model.now]
            return {'op': kind, 'to': rng.choice(choices)}
        if kind == 'cancel':
            return {'op': kind, 'label': rng.choice(active)}
        return {'op': kind}


def run_seed(seed, operations_count=300):
    ARTIFACTS.mkdir(parents=True, exist_ok=True)
    rng = random.Random(seed)
    identities = random.Random(seed + 2000000)
    operations = []
    started = time.monotonic()
    with tempfile.TemporaryDirectory(dir=ROOT) as folder, patch(
            'joblab.queue.uuid.uuid4', side_effect=lambda: uuid.UUID(int=identities.getrandbits(128))):
        path = str(Path(folder) / 'scheduler.db')
        runner = SchedulerRunner(path)
        try:
            for step in range(operations_count):
                operation = runner.operation(rng, step)
                operations.append(operation)
                runner.apply(operation)
            for required in ('schedule', 'advance', 'tick', 'cancel', 'reopen'):
                if runner.counts.get(required, 0) == 0:
                    raise AssertionError('coverage missing: ' + required)
            receipt = {'seed': seed, 'operations': operations_count, 'counts': runner.counts,
                       'schedules': len(runner.model.schedules), 'fires': len(runner.model.fires),
                       'elapsed_seconds': time.monotonic() - started, 'status': 'passed',
                       'trace_sha256': hashlib.sha256(json.dumps(operations, sort_keys=True).encode()).hexdigest()}
            (ARTIFACTS / ('seed-%d.json' % seed)).write_text(
                json.dumps({'receipt': receipt, 'operations': operations}, indent=2) + '\n', encoding='utf-8')
            return receipt
        except BaseException as exc:
            failure = {'seed': seed, 'failed_step': len(operations), 'operations': operations,
                       'error': repr(exc)}
            failure_path = ARTIFACTS / ('failure-seed-%d.json' % seed)
            if not failure_path.exists():
                failure_path.write_text(json.dumps(failure, indent=2) + '\n', encoding='utf-8')
            raise
        finally:
            runner.q.close()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--start', type=int, required=True)
    parser.add_argument('--end', type=int, required=True)
    parser.add_argument('--operations', type=int, default=300)
    args = parser.parse_args()
    if not (0 <= args.start < args.end <= 1000) or args.operations < 1:
        raise SystemExit('use 0 <= start < end <= 1000 and positive operations')
    receipts = []
    totals = {}
    started = time.monotonic()
    for seed in range(args.start, args.end):
        receipt = run_seed(seed, args.operations)
        receipts.append(receipt)
        for key, value in receipt['counts'].items():
            totals[key] = totals.get(key, 0) + value
    summary = {'seed_start': args.start, 'seed_end_exclusive': args.end,
               'seed_count': len(receipts), 'operations_per_seed': args.operations,
               'total_operations': len(receipts) * args.operations,
               'operation_totals': totals, 'total_fires': sum(r['fires'] for r in receipts),
               'elapsed_seconds': time.monotonic() - started, 'status': 'passed'}
    (ARTIFACTS / ('summary-%d-%d.json' % (args.start, args.end - 1))).write_text(
        json.dumps({'summary': summary, 'receipts': receipts}, indent=2) + '\n', encoding='utf-8')
    print(json.dumps(summary, sort_keys=True))


if __name__ == '__main__':
    main()
